/**
 * @event
 * @name scwin.ipt_noSelected_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_noSelected_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_noSelected_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.noSelected()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil01010.ipt_noSelected_onclick' }); }
};

/**
