/**
 * @method
 * @name scwin.selected
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.selected = async function () {
    /* sdd-asis-lifecycle:begin fn_selected — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const formObj = (document.codeForm || { elements: [] });
    let ndx = "";
    const selectArr = new Array(2);
    let code = "";
    let name = "";
    if (((!$c.util.getComponent('ipt_noSelected') || typeof $c.util.getComponent('ipt_noSelected').getValue !== 'function') ? (console.warn('[sdd] .checked 대상 미해결: ipt_noSelected'), false) : ($c.util.getComponent('ipt_noSelected').getValue() != null && String($c.util.getComponent('ipt_noSelected').getValue()) !== '')) === false) {
        for (i = 0; i < $c.util.getComponent("slc_selIndcode").length; i++) {
            if ($c.util.getComponent("slc_selIndcode").options[i].selected) {
                if (name.length === "") {
                    name = $c.util.getComponent("slc_selIndcode").options[i].text;
                    code = $c.util.getComponent("slc_selIndcode").options[i].value;
                } else {
                    name = name + ",\n" + $c.util.getComponent("slc_selIndcode").options[i].text;
                    code = code + "," + $c.util.getComponent("slc_selIndcode").options[i].value;
                }
                ndx++;
            }
        }
        if (ndx == 0) {
            await $c.win.alert("입력할 사유를  선택하십시오");
            return;
        } else {
            scwin.frame.fn_setSelectedData($c.util.getComponent("ipt_formKey").getValue(), $c.util.getComponent("ipt_keyValue").getValue(), decodeURIComponent($c.util.getComponent("ipt_returnKey").getValue()), code, name);
            $c.win.closePopup();
        }
    } else {
        code = "-";
        name = "-";
        scwin.frame.fn_setSelectedData($c.util.getComponent("ipt_formKey").getValue(), $c.util.getComponent("ipt_keyValue").getValue(), decodeURIComponent($c.util.getComponent("ipt_returnKey").getValue()), code, name);
        $c.win.closePopup();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.noSelected
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.noSelected = function () {
    /* sdd-asis-lifecycle:begin fn_noSelected — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const formObj = (document.codeForm || { elements: [] });
    if (((!$c.util.getComponent('ipt_noSelected') || typeof $c.util.getComponent('ipt_noSelected').getValue !== 'function') ? (console.warn('[sdd] .checked 대상 미해결: ipt_noSelected'), false) : ($c.util.getComponent('ipt_noSelected').getValue() != null && String($c.util.getComponent('ipt_noSelected').getValue()) !== '')) === true) {
        $c.util.getComponent('slc_selIndcode').setDisabled(true);
    } else {
        $c.util.getComponent('slc_selIndcode').setDisabled(false);
    }
    /* sdd-asis-lifecycle:end */
};
